import json,html,shutil
from matplotlib.colors import Normalize,to_hex
from matplotlib import colormaps
ROOT=Path(__file__).resolve().parents[3];R=ROOT/'results/2026-10-15-abstention-overview';D=json.loads((R/'evidence.json').read_text());H=html.escape
cmap=colormaps['YlOrRd'];norm=Normalize(*D['observational_scale'])
oldbase='https://rakaar.github.io/qwen3-molt-exploration/results/2026-10-15-vampire-intermediate/'
newbase='https://rakaar.github.io/qwen3-molt-exploration/results/2026-10-15-six-new-abstentions/'
obsbase='https://rakaar.github.io/qwen3-molt-exploration/results/2026-10-14-passage-answer-gates/'

def tokens(r):
 out=[]
 for t in r['tokens']:
  g=max(0,t['gate']);color='white' if norm(g)>.65 else '#152d34';word=t['token'].replace(' ','·').replace('\n','↵')
  title=f"Token {t['answer_position']}; gate {g:.6f}; raw {t['raw']:.6f}"
  out.append(f'<span class="token" style="background:{to_hex(cmap(norm(g)))};color:{color}" title="{H(title)}"><b>{H(word)}</b><small>{t["answer_position"]} · {g:.2f}</small></span>')
 return ''.join(out)

def natural_card(r):
 group='Model made up an answer' if r['group']=='made_up' else 'Natural “I don’t know”'
 return f'<article class="natural-card"><div class="small-label">{H(group)} · {H(r["id"])}</div><h3>{H(r["question"])}</h3><p class="native-answer">{H(r["answer"])}</p><p class="mean"><strong>Mean gate {r["mean_gate"]:.3f}</strong><span>{r["active_tokens"]}/{r["visible_tokens"]} active tokens</span></p><div class="tokens">{tokens(r)}</div></article>'

def comparison_row(c):
 status='Clear abstention' if c['success'] else 'No clear conversion';st='Successful tested addition' if c['success'] else 'Representative failed trial';url=oldbase if c['id'].startswith('P') else newbase
 return f'<tr data-success="{str(c["success"]).lower()}"><td data-label="Question"><span class="case-id">{H(c["id"])}</span><strong>{H(c["question"])}</strong><details><summary>Read passage</summary><p>{H(c["context"])}</p></details></td><td data-label="Baseline model">{H(c["baseline"])}</td><td data-label="Steered model"><span class="status {"good" if c["success"] else "bad"}">{status}</span><p>{H(c["steered"])}</p><a class="small-link" href="{url}index.html">Every tested answer ↗</a></td><td data-label="Added coefficient"><strong>+{c["strength"]}</strong><small>{st}</small></td></tr>'

cards=''.join(natural_card(D['observational_examples'][i]) + natural_card(D['observational_examples'][i+3]) for i in range(3))
rows=''.join(comparison_row(c) for c in D['cases']);bat=next(c for c in D['cases'] if c['id']=='P2-U5')
ref='The passage says vampire bats can spread rabies. It does not state what they do not spread, so that answer cannot be determined from the passage.'
